def _key(name: str) -> int:
    val = getattr(glfw, f"KEY_{name.upper()}", None)
    if val is None:
        raise ValueError(f"Unknown GLFW key: {name}")
    return val


# ===================================================================
# run()
# ===================================================================

JOG_JOINT_STEP = 0.05   # rad per viewer frame while Q / E is held
JOG_GRIP_STEP = 0.003   # m per viewer frame (finger travel is 0 closed .. 0.044 open)
GRIP_IDX = 7            # selection index 0-6 = joints 1-7, 7 = gripper (key 8)


def build_jog_tables(model):
    """Per side, 8 selectable items: (actuator ids, (lo, hi), step).

    Items 0-6 are arm joints 1-7; item 7 is the gripper, whose two fingers
    move together (0 = closed, 0.044 m = open on both hands).
    """
    def aid(name):
        a = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, name)
        if a < 0:
            raise RuntimeError(f"Actuator '{name}' not in model.")
        return a

    def jrange(a):
        return tuple(model.jnt_range[model.actuator_trnid[a, 0]])

    tables = {}
    for side in ("left", "right"):
        items = []
        for i in range(1, 8):
            a = aid(f"{side}_joint{i}_ctrl")
            items.append(([a], jrange(a), JOG_JOINT_STEP))
        f = [aid(f"{side}_finger1_ctrl"), aid(f"{side}_finger2_ctrl")]
        items.append((f, jrange(f[0]), JOG_GRIP_STEP))
        tables[side] = items
    return tables


def jog_step(sel, direction, targets, tables, teleop_on):
    """Move the selected arm joint / gripper one step (direction -1, 0 or +1).

    Writes into `targets` (the per-actuator hold targets, the same array
    teleop writes), clamped to the joint's range. While teleop is on it owns
    the arm joints, so only the gripper responds then.
    """
    if direction == 0 or (teleop_on and sel["idx"] != GRIP_IDX):
        return
    ids, (lo, hi), step = tables[sel["side"]][sel["idx"]]
    targets[ids] = np.clip(targets[ids[0]] + direction * step, lo, hi)


def install_preview_capture(store):
    """Route the MediaPipe preview into `store` instead of an OpenCV window.

    The camera library draws its pose-overlay frame with cv2.imshow and quits
    the whole device if its window stops being visible. Replacing both
    functions lets the viewer draw the frame itself, as one more inset next to
    the simulated cameras: no second window to place on a small VM screen
    (mutter ignores window moves), and the frame is stored in
    store["preview_frame"] (BGR) for snapshots.
    """
    import cv2
    orig_get_prop = cv2.getWindowProperty

    def imshow(name, img):
        store["preview_frame"] = img.copy()

    def get_window_property(name, prop):
        if name == PREVIEW_WINDOW:
            return 1.0  # "visible"; there is deliberately no window
        return orig_get_prop(name, prop)

    cv2.imshow = imshow
    cv2.getWindowProperty = get_window_property


class _FakeSource:
    """Scripted operator for testing without a webcam (CC_FAKE_TELEOP=1).

    In view for 4 s, out of view for 4 s, repeating. Draws a synthetic
    preview frame through cv2.imshow like the real camera thread does.
    """

    def __init__(self):
        self.t0 = time.monotonic()

    def get_frame(self):
        import cv2
        ph = (time.monotonic() - self.t0) % 8.0
        in_view = ph < 4.0
        img = np.full((480, 640, 3), 70 if in_view else 25, np.uint8)
        cv2.circle(img, (int(100 + 440 * (ph / 8.0)), 240), 40,
                   (0, 200, 255) if in_view else (80, 80, 80), -1)
        cv2.putText(img, "FAKE OPERATOR " + ("in view" if in_view else "out of view"),
                    (30, 60), cv2.FONT_HERSHEY_SIMPLEX, 1.0, (255, 255, 255), 2)
        cv2.imshow(PREVIEW_WINDOW, img)
        return object() if in_view else None  # any non-None = engaged

    def cleanup(self):
        pass


class _FakeSession:
    """Stand-in solver for _FakeSource: swings every arm joint gently."""

    def __init__(self, lo, hi):
        self.lo, self.hi = lo, hi
        self.t0 = time.monotonic()

    def reset(self, *args):
        pass

    def solve(self, frame, engaged, q_current_right, q_current_left):
        from types import SimpleNamespace
        ph = time.monotonic() - self.t0
        out = {}
        for sd in ("right", "left"):
            goal = 0.4 * np.sin(ph + np.arange(7))
            out[f"q_goal_{sd}"] = np.clip(goal, self.lo[sd], self.hi[sd])
        return SimpleNamespace(**out)


def _perf_settings():
    """Viewer / camera performance settings, overridable with CC_* env vars.

    Defaults are the fastest combination measured on the VirtualBox VM
    (about 130 ms/frame, was ~600-1000): viewer shadows/reflections off,
    one camera rendered per camera tick (take-turns, a VM performance
    setting; use CC_ROUNDROBIN=0 to record demos with every camera updating
    at CAMERA_HZ), vsync off paced to VIEWER_HZ.
    Resolution, shadow map size and window size made no measurable difference.

    CC_VIEW_SHADOWS=1  viewer shadows+reflections on   CC_ROUNDROBIN=0  render all cameras on every tick (demo recording)
    CC_CAM_SHADOWS=0   camera shadows off (washes out wrist cams)
    CC_VSYNC=1         vsync on (frames stall ~1 s if the window is hidden)
    CC_CAM_RES=WxH  CC_CAM_HZ=N  CC_SHADOWSIZE=N  CC_WIN=WxH  CC_HUD=0  CC_INSETS=0
    CC_FAKE_TELEOP=1   scripted fake operator + solver (no webcam needed)
    CC_BENCH_KEYS=10-20:E,30:T  hold keys on those frames (testing)   CC_BENCH_SNAP_FRAME=n
    CC_FINISH=1        glFinish after each swap
    CC_BENCH_FRAMES=N  run N frames, print per-phase timings, then exit
    CC_BENCH_SNAP=dir  save main view + camera images at frame 15
    """
    e = os.environ.get
    def wh(v):
        return tuple(int(x) for x in v.lower().split("x")) if v else None
    return {
        "frames": int(e("CC_BENCH_FRAMES", "0")),
        "cam_res": wh(e("CC_CAM_RES")),
        "cam_hz": float(e("CC_CAM_HZ")) if e("CC_CAM_HZ") else None,
        "roundrobin": e("CC_ROUNDROBIN") != "0",
        "cam_shadows": None if e("CC_CAM_SHADOWS") is None
                       else e("CC_CAM_SHADOWS") == "1",
        "view_shadows": e("CC_VIEW_SHADOWS") == "1",
        "shadowsize": int(e("CC_SHADOWSIZE")) if e("CC_SHADOWSIZE") else None,
        "win": wh(e("CC_WIN")) or (1280, 960),
        "vsync": int(e("CC_VSYNC", "0")),
        "snap_dir": e("CC_BENCH_SNAP"),
        "finish": e("CC_FINISH") == "1",
        "fake_teleop": e("CC_FAKE_TELEOP") == "1",
        "inject": e("CC_BENCH_KEYS", ""),
        "snap_frame": int(e("CC_BENCH_SNAP_FRAME", "15")),
        "hud": e("CC_HUD") != "0",
        "insets": e("CC_INSETS") != "0",
    }


def run(scene: str, spawn_pos, groups: list[dict], policy,
        mode: str = "manual", camera: int = 0, preview: bool = True,
        snapshot_every: float = 0.0, snapshot_dir: str | None = None):
    """
    Main entry point.

    Args:
        scene:      Path to MuJoCo scene XML (relative to PROJECT_ROOT).
        spawn_pos:  [x, y, z] or None to use the XML default.
        groups:     List of control-group dicts (see CONTROL_GROUPS).
        policy:     Callable(observation, t) -> target angles array, or None.
                    When None, auto groups are skipped (zero ctrl) and only
                    manual groups respond — i.e. pure keyboard teleop.
    """

    bench = _perf_settings()
    global CAMERA_SHADOWS, SHOW_HUD, SHOW_CAMERA_INSETS
    SHOW_HUD = SHOW_HUD and bench["hud"]
    SHOW_CAMERA_INSETS = SHOW_CAMERA_INSETS and bench["insets"]
    if bench["cam_res"]:
        for cs in robot_specs.CAMERA_SPECS:
            cs["resolution"] = bench["cam_res"]
    if bench["cam_hz"]:
        robot_specs.CAMERA_HZ = bench["cam_hz"]
    if bench["cam_shadows"] is not None:
        CAMERA_SHADOWS = bench["cam_shadows"]

    # --- Load scene ---
    sim   = RobotSimulator(model_path=str(PROJECT_ROOT / scene),
                           cameras=robot_specs.CAMERA_SPECS)
    model = sim.model
    data  = sim.data

    # --- Multi-rate schedule (all derived from the model timestep) ---
    physics_hz = 1.0 / model.opt.timestep

    def _every(hz, what):
        n = physics_hz / hz
        if abs(n - round(n)) > 1e-6:
            raise ValueError(f"physics {physics_hz:.1f} Hz is not an integer "
                             f"multiple of {what} {hz} Hz")
        return int(round(n))

    pd_every  = _every(robot_specs.PD_HZ, "PD")
    cam_every = _every(robot_specs.CAMERA_HZ, "camera")
    # Sim choice: the viewer rate need not divide physics evenly (750/60 =
    # 12.5), so round; the step counter below is global, so camera ticks
    # stay exactly every cam_every physics steps regardless.
    steps_per_frame = max(1, round(physics_hz / VIEWER_HZ))
    warmup_steps  = round(WARMUP_SEC * physics_hz)
    resettle_steps = round(RESETTLE_SEC * physics_hz)
    print(f"Rates: physics {physics_hz:.0f} Hz | PD every {pd_every} step(s) "
          f"({physics_hz / pd_every:.0f} Hz) | cameras every {cam_every} steps "
          f"({physics_hz / cam_every:.0f} Hz, "
          f"{'one camera per tick' if bench['roundrobin'] else 'all cameras per tick'}) "
          f"| viewer {steps_per_frame} steps/frame "
          f"(~{physics_hz / steps_per_frame:.0f} Hz)")

    # --- Resolve actuator IDs per group ---
    claimed = set()
    resolved = []

    for g in groups:
        spec = g["actuators"]
        if spec == "remaining":
            resolved.append(None)
        else:
            ids = []
            for name in spec:
                aid = mujoco.mj_name2id(
                    model, mujoco.mjtObj.mjOBJ_ACTUATOR, name)
                if aid < 0:
                    raise RuntimeError(f"Actuator '{name}' not in model.")
                ids.append(aid)
            claimed.update(ids)
            resolved.append(ids)

    for i, g in enumerate(groups):
        if resolved[i] is None:
            resolved[i] = sorted(set(range(model.nu)) - claimed)
            claimed.update(resolved[i])

    for g, ids in zip(groups, resolved):
        names = [model.actuator(a).name for a in ids]
        print(f"  {g['name']:18s}  {g['mode']:8s}  "
              f"act_ids={ids}  ({', '.join(names)})")

    # Unclaimed actuators hold their settled position so the robot
    # doesn't collapse.  This is not "auto" — it's just gravity
    # compensation for joints nobody is actively controlling.
    unclaimed_ids = sorted(set(range(model.nu)) - claimed)
    if unclaimed_ids:
        names = [model.actuator(a).name for a in unclaimed_ids]
        print(f"  {'(hold position)':18s}  {'':8s}  "
              f"act_ids={unclaimed_ids}  ({', '.join(names)})")

    # --- Find the free joint for velocity-based base driving ---
    free_joint_id = None
    for j in range(model.njnt):
        if model.jnt_type[j] == 0:  # mjJNT_FREE
            free_joint_id = j
            break
    if free_joint_id is not None:
        base_dof = model.jnt_dofadr[free_joint_id]
        print(f"  Free joint '{model.joint(free_joint_id).name}' "
              f"dof_adr={base_dof} (velocity drive target)")
    else:
        base_dof = None
        print("  WARNING: no free joint found — velocity drive disabled")

    # --- PD controller ---
    controller = RobotController(model)
    logger     = TrajectoryLogger()

    # --- Per-group state ---
    drive_state = {}
    joint_state = {}

    for g, ids in zip(groups, resolved):
        if g["mode"] == "manual" and g.get("type") == "drive":
            drive_state[g["name"]] = {"linear": 0.0, "angular": 0.0}
        if g["mode"] == "manual" and g.get("type") == "joint":
            joint_state[g["name"]] = np.zeros(len(ids))

    # Resolve key bindings
    drive_keys = {}
    for g in groups:
        if g["mode"] == "manual" and g.get("type") == "drive":
            dk = g["keys"]
            drive_keys[g["name"]] = {
                action: [_key(k) for k in key_list]
                for action, key_list in dk.items()
            }

    joint_keys = {}
    for g, ids in zip(groups, resolved):
        if g["mode"] == "manual" and g.get("type") == "joint":
            jk = g["keys"]
            joint_keys[g["name"]] = {
                aid: {
                    "up":   [_key(k) for k in jk.get(model.actuator(aid).name, {}).get("up", [])],
                    "down": [_key(k) for k in jk.get(model.actuator(aid).name, {}).get("down", [])],
                }
                for aid in ids
            }

    # --- Camera target ---
    base_body_id = mujoco.mj_name2id(
        model, mujoco.mjtObj.mjOBJ_BODY, "base_link")
    if base_body_id < 0:
        base_body_id = 1

    # --- Spawn and settle ---
    if spawn_pos is not None:
        data.qpos[0:3] = spawn_pos
        mujoco.mj_forward(model, data)

    print("Settling physics ...")
    # Hold arm joints at home (zero) during warmup so they settle under
    # PD control instead of drooping limp and then oscillating when the
    # main loop starts.
    hold_qpos_targets = np.zeros(model.nu)
    for i in range(warmup_steps):
        if i % pd_every == 0:
            warmup_ctrl = controller.step(hold_qpos_targets,
                {"joint_angles": data.qpos, "joint_velocities": data.qvel})
            # Only apply hold ctrl for unclaimed actuators; zero the rest
            for aid in range(model.nu):
                if aid in unclaimed_ids:
                    data.ctrl[aid] = warmup_ctrl[aid]
                else:
                    data.ctrl[aid] = 0.0
        mujoco.mj_step(model, data)
    print(f"Settled at z={data.qpos[2]:.4f}")

    # Capture the natural resting pose after warmup — arms hanging down
    # under gravity.  Zero velocities so they're still, then re-settle
    # briefly with PD holding at this pose.  The PD doesn't need to fight
    # gravity (it's already at equilibrium) — it just resists disturbances
    # when the base moves.
    hold_qpos_targets = np.zeros(model.nu)
    for aid in unclaimed_ids:
        qadr = model.jnt_qposadr[model.actuator_trnid[aid, 0]]
        hold_qpos_targets[aid] = data.qpos[qadr]  # actual drooped angle
        vadr = model.jnt_dofadr[model.actuator_trnid[aid, 0]]
        data.qvel[vadr] = 0.0  # kill any residual swing
    mujoco.mj_forward(model, data)

    # Brief re-settle with PD active so everything stabilizes
    for i in range(resettle_steps):
        if i % pd_every == 0:
            hold_ctrl = controller.step(hold_qpos_targets,
                {"joint_angles": data.qpos, "joint_velocities": data.qvel})
            for aid in unclaimed_ids:
                data.ctrl[aid] = hold_ctrl[aid]
        mujoco.mj_step(model, data)
    print(f"Arms locked at resting pose, re-settled at z={data.qpos[2]:.4f}")

    # --- Teleop setup (webcam -> MediaPipe -> geo_kin SEW-Mimic) ---
    # Code generated by Claude — teleop mode using SEW-Mimic retargeting (geo_kin)
    teleop = None
    if mode == "teleop":
        import atexit
        from geo_kin_core.types import RetargetFrame

        arm_ids = {}
        arm_qadr = {}
        arm_lo = {}
        arm_hi = {}
        for side in ("right", "left"):
            ids = [mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR,
                                     f"{side}_joint{i}_ctrl") for i in range(1, 8)]
            jids = [model.actuator_trnid[a, 0] for a in ids]
            arm_ids[side] = ids
            arm_qadr[side] = [model.jnt_qposadr[j] for j in jids]
            arm_lo[side] = np.array([model.jnt_range[j, 0] for j in jids])
            arm_hi[side] = np.array([model.jnt_range[j, 1] for j in jids])

        # The arms start in MANUAL (keyboard); T switches them to the webcam
        # operator and back, so the base can be driven into place first.
        teleop = {"warned": set(), "engaged": False, "on": False}
        if bench["fake_teleop"]:
            session = _FakeSession(arm_lo, arm_hi)
            source = _FakeSource()
            print("Teleop: FAKE scripted operator (CC_FAKE_TELEOP=1), no webcam")
        else:
            from openarm_teleop.session import make_session
            from xrt_devices.integrations.geo_kin import MediaPipeDeviceAdapter
            # Solver first, so a licence problem can't leave a camera running.
            session = make_session()
            session.reset(data.qpos[arm_qadr["right"]].copy(),
                          data.qpos[arm_qadr["left"]].copy())
            # display=True makes the library draw the pose overlay on the
            # camera feed; install_preview_capture hands that frame to the
            # viewer instead of opening a window.
            source = MediaPipeDeviceAdapter(camera_id=camera, display=preview)
            atexit.register(source.cleanup)
        if preview:
            install_preview_capture(teleop)
        print(f"Teleop: camera {camera}, preview={'on' if preview else 'off'}. "
              f"Arms start MANUAL; press T for teleop, then raise both arms "
              f"to shoulder height to engage.")

    # --- Snapshots (press P in the MuJoCo window, or --snapshot-every N) ---
    import cv2
    import time as _time
    snap_dir = Path(snapshot_dir) if snapshot_dir else PROJECT_ROOT / "snapshots"
    snap_state = {"last": _time.time(), "p_down": False}
    hud_state = {"last": _time.time(), "ms": 0.0}
    inset_cache = {}

    def save_snapshot(rgb):
        snap_dir.mkdir(parents=True, exist_ok=True)
        stamp = _time.strftime("%H%M%S")
        cv2.imwrite(str(snap_dir / f"sim_{stamp}.png"),
                    cv2.cvtColor(np.flipud(rgb), cv2.COLOR_RGB2BGR))
        pf = teleop.get("preview_frame") if teleop else None
        if pf is not None:
            cv2.imwrite(str(snap_dir / f"camera_{stamp}.png"), pf)
        print(f"Snapshot saved: {snap_dir}/sim_{stamp}.png"
              f"{' + camera' if pf is not None else ''}")

    # --- GLFW ---
    glfw.set_error_callback(
        lambda err, desc: print(f"GLFW error {err}: {desc}"))
    if not glfw.init():
        raise RuntimeError("Could not initialise GLFW")
    win_w, win_h = bench["win"]
    if mode == "teleop":
        # Use the whole screen width so the four insets (3 simulated cameras
        # plus the operator webcam) fit. The window must be created at its
        # final size, hidden, and positioned BEFORE it is shown: mutter
        # auto-maximizes a window bigger than the screen and then ignores
        # later move/resize requests.
        vm = glfw.get_video_mode(glfw.get_primary_monitor())
        x0 = 0
        win_w, win_h = vm.size.width, vm.size.height - 80
        glfw.window_hint(glfw.VISIBLE, glfw.FALSE)
    window = glfw.create_window(win_w, win_h, "Combined Controller", None, None)
    if not window:
        glfw.terminate()
        raise RuntimeError("GLFW window creation failed")
    if mode == "teleop":
        glfw.set_window_pos(window, x0, 30)
        glfw.show_window(window)
    glfw.make_context_current(window)
    glfw.swap_interval(bench["vsync"])

    model.vis.global_.fovy = FOVY_DEG
    cam = mujoco.MjvCamera()
    opt = mujoco.MjvOption()
    mujoco.mjv_defaultCamera(cam)
    mujoco.mjv_defaultOption(opt)
    cam.distance  = CAM_DISTANCE
    cam.elevation = CAM_ELEVATION
    cam.azimuth   = 90

    scene_vis = mujoco.MjvScene(model, maxgeom=10_000)
    if mode == "teleop" or not bench["view_shadows"]:
        # The VM GPU renders this scene at ~5 fps with shadows/reflections,
        # too slow for the arms to track the operator.
        scene_vis.flags[mujoco.mjtRndFlag.mjRND_SHADOW] = 0
        scene_vis.flags[mujoco.mjtRndFlag.mjRND_REFLECTION] = 0
    if bench["shadowsize"]:
        model.vis.quality.shadowsize = bench["shadowsize"]
    context   = mujoco.MjrContext(model, mujoco.mjtFontScale.mjFONTSCALE_150)

    # Cameras share this GL context (offscreen buffer was sized in
    # RobotSimulator). Render once so frames exist before the first camera tick.
    rig = CameraRig(model, robot_specs.CAMERA_SPECS, context,
                    shadows=CAMERA_SHADOWS)
    rig.render(data)
    cam_dir = PROJECT_ROOT / CAMERA_SNAPSHOT_DIR

    tm = {"phys": 0.0, "cam": 0.0, "render": 0.0, "hud_insets": 0.0,
          "swap_poll": 0.0}
    pc = _time.perf_counter
    cam_names = [cs["name"] for cs in robot_specs.CAMERA_SPECS]
    cam_tick = 0
    t_bench0 = None
    rows = []  # per-frame (had_cam_tick, ms total, cam, render, swap)
    tick_prev = 0.0
    r_prev = 0.0
    if bench["frames"]:
        try:
            from OpenGL.GL import glGetString, GL_RENDERER
            print("BENCH GL renderer:", glGetString(GL_RENDERER))
        except Exception as ex:
            print("BENCH GL renderer unknown:", ex)

    logging_active = False
    prev_l = False
    prev_c = False
    prev_t = False
    step_count = 0
    frame  = 0

    # Test hook: CC_BENCH_KEYS="10-20:E,30:T" holds those keys on those frames.
    injected = set()
    for tok in bench["inject"].split(","):
        if ":" in tok:
            fr, kname = tok.split(":", 1)
            lo_f, _, hi_f = fr.partition("-")
            for f_ in range(int(lo_f), int(hi_f or lo_f) + 1):
                injected.add((f_, _key(kname)))

    def held(key):
        return glfw.get_key(window, key) == glfw.PRESS \
            or (frame, key) in injected

    jog_tables = build_jog_tables(model)
    jog_sel = {"side": "right", "idx": 0}   # selected arm side and item
    digit_keys = [_key(str(n)) for n in range(1, 9)]
    prev_tab = False
    prev_digits = [False] * 8

    def set_teleop(on):
        """Switch the arms between MANUAL keys and the TELEOP webcam operator.

        Manual jogging and teleop write the same per-actuator hold targets,
        so neither side needs syncing: each continues from the current target.
        In MANUAL the keys can move any arm joint and gripper.
        """
        if on == teleop["on"]:
            return
        if on:
            session.reset(data.qpos[arm_qadr["right"]].copy(),
                          data.qpos[arm_qadr["left"]].copy())
            teleop["engaged"] = False
        teleop["on"] = on
        print("Arms: TELEOP (webcam operator; raise both arms to engage; "
              "grippers stay on keys)" if on else
              "Arms: MANUAL (keys: Tab arm, 1-7 joint, 8 gripper, Q/E jog)")

    hud_keys = [("WASD", "drive"), ("Spc", "stop"), ("Tab", "L/R arm"),
                ("1-7", "joint"), ("8", "grip"), ("Q E", "jog -/+")] + \
        ([("T", "man/tele")] if teleop is not None else []) + \
        [("C", "cam imgs"), ("P", "snap"), ("L", "log"), ("Esc", "quit")]

    print(f"\nBase:  W/UP=fwd  S/DOWN=back  A/LEFT=left  D/RIGHT=right  SPACE=stop")
    print(f"Arms:  Tab=left/right  1-7=joint  8=gripper  Q/E=jog -/+ (E opens gripper)")
    print(f"L=log  C=save camera images  Esc=quit")
    if teleop is not None:
        print(f"T=toggle arms MANUAL / TELEOP (webcam); base keys work in both")
    print(f"--- entering loop ---")

    # ---------------------------------------------------------------
    while not glfw.window_should_close(window):
      try:
        t_f0 = pc()
        obs = sim.get_observation()
        t   = sim.get_time()

        # Per-frame targets for the PD loop; the PD itself runs in the
        # substep loop below on live state. Actuators without PD get zero ctrl.
        targets = np.zeros(model.nu)
        pd_mask = np.zeros(model.nu, dtype=bool)

        policy_targets = policy(obs, t) if policy is not None else None

        if teleop is not None:
            cur_t_key = held(glfw.KEY_T)
            if cur_t_key and not prev_t:
                set_teleop(not teleop["on"])
            prev_t = cur_t_key

        # Manual arm / gripper jogging: Tab side, 1-8 item, Q/E move.
        cur_tab = held(glfw.KEY_TAB)
        if cur_tab and not prev_tab:
            jog_sel["side"] = "left" if jog_sel["side"] == "right" else "right"
        prev_tab = cur_tab
        for n, k in enumerate(digit_keys):
            cur_d = held(k)
            if cur_d and not prev_digits[n]:
                jog_sel["idx"] = n
            prev_digits[n] = cur_d
        jog_step(jog_sel, int(held(glfw.KEY_E)) - int(held(glfw.KEY_Q)),
                 hold_qpos_targets, jog_tables,
                 teleop is not None and teleop["on"])

        # --- Compute velocity command for base (before substep loop) ---
        base_vx = 0.0
        base_vy = 0.0
        base_wz = 0.0

        for g, ids in zip(groups, resolved):

            if g["mode"] == "auto":
                if policy_targets is not None:
                    for aid in ids:
                        targets[aid] = policy_targets[aid]
                        pd_mask[aid] = True

            elif g["mode"] == "manual" and g.get("type") == "drive":
                ds = drive_state[g["name"]]
                dk = drive_keys[g["name"]]
                dp = g.get("drive_params", {})
                incr        = dp.get("incr", 0.1)
                max_lin_vel = dp.get("max_linear_vel", 1.5)
                max_ang_vel = dp.get("max_angular_vel", 2.0)

                # Ramp linear/angular commands (cruise control)
                ds["linear"] += (incr if any(held(k) for k in dk["forward"]) else 0.0) \
                              - (incr if any(held(k) for k in dk["backward"]) else 0.0)
                ds["angular"] += (incr if any(held(k) for k in dk["left"]) else 0.0) \
                               - (incr if any(held(k) for k in dk["right"]) else 0.0)
                ds["linear"]  = max(-1.0, min(ds["linear"],  1.0))
                ds["angular"] = max(-1.0, min(ds["angular"], 1.0))

                if any(held(k) for k in dk.get("stop", [])):
                    # Ramp back to zero at the same rate as the accel
                    # ramp (incr/step) instead of snapping instantly —
                    # avoids a velocity discontinuity at stop, the same
                    # kind of instant-stop artifact investigated for the
                    # scripted test scenario (see
                    # data/arm_swing_diagnostics/rampstop_*).
                    if ds["linear"] > 0:
                        ds["linear"] = max(0.0, ds["linear"] - incr)
                    else:
                        ds["linear"] = min(0.0, ds["linear"] + incr)
                    if ds["angular"] > 0:
                        ds["angular"] = max(0.0, ds["angular"] - incr)
                    else:
                        ds["angular"] = min(0.0, ds["angular"] + incr)

                # Convert normalized commands to velocities
                lin_vel = ds["linear"] * max_lin_vel
                ang_vel = ds["angular"] * max_ang_vel

                # Project forward velocity into world frame using robot yaw
                qw, qx, qy, qz = data.qpos[3:7]
                yaw = math.atan2(
                    2.0 * (qw * qz + qx * qy),
                    1.0 - 2.0 * (qy * qy + qz * qz))
                base_vx = lin_vel * math.cos(yaw)
                base_vy = lin_vel * math.sin(yaw)
                base_wz = ang_vel

                # Don't set wheel motor ctrl — velocity drive bypasses them

            elif g["mode"] == "manual" and g.get("type") == "joint":
                js   = joint_state[g["name"]]
                jk   = joint_keys[g["name"]]
                step = g.get("step_size", 0.05)

                if teleop is not None and teleop["on"]:
                    # Teleop owns these joints: track its targets, ignore keys.
                    for aid in ids:
                        targets[aid] = hold_qpos_targets[aid]
                        pd_mask[aid] = True
                    continue

                for i, aid in enumerate(ids):
                    if any(held(k) for k in jk[aid]["up"]):
                        js[i] += step
                    if any(held(k) for k in jk[aid]["down"]):
                        js[i] -= step

                for i, aid in enumerate(ids):
                    targets[aid] = js[i]
                    pd_mask[aid] = True

        # --- Teleop: arm PD targets from session.solve() ---
        if teleop is not None:
            tframe = source.get_frame()  # also keeps the preview fresh
            if teleop["on"]:
                q_cur = {sd: data.qpos[arm_qadr[sd]].copy() for sd in arm_ids}
                out = session.solve(
                    tframe if tframe is not None else RetargetFrame(),
                    engaged=tframe is not None,
                    q_current_right=q_cur["right"], q_current_left=q_cur["left"])
                if (tframe is not None) != teleop["engaged"]:
                    teleop["engaged"] = tframe is not None
                    print("Teleop: " + ("ENGAGED" if teleop["engaged"]
                                        else "tracking lost — holding last pose"))
                if tframe is not None:
                    for sd in ("right", "left"):
                        goal = getattr(out, f"q_goal_{sd}", None)
                        if goal is None:
                            if (sd, "none") not in teleop["warned"]:
                                teleop["warned"].add((sd, "none"))
                                print(f"Teleop WARNING: solve() gave no q_goal_{sd}")
                            continue
                        goal = np.asarray(goal, dtype=float)
                        if goal.shape != (7,) or not np.isfinite(goal).all() \
                                or np.abs(goal).max() > math.pi:
                            if (sd, "range") not in teleop["warned"]:
                                teleop["warned"].add((sd, "range"))
                                print(f"Teleop WARNING: q_goal_{sd} invalid or "
                                      f"outside ±pi, frame ignored: {goal.round(2)}")
                            continue
                        clipped = np.clip(goal, arm_lo[sd], arm_hi[sd])
                        if (sd, "clip") not in teleop["warned"] and \
                                not np.allclose(clipped, goal):
                            teleop["warned"].add((sd, "clip"))
                            print(f"Teleop: q_goal_{sd} clipped to joint limits "
                                  f"(first seen: {goal.round(2)})")
                        cur_t = hold_qpos_targets[arm_ids[sd]]
                        max_d = TELEOP_MAX_JOINT_VEL / 60.0
                        hold_qpos_targets[arm_ids[sd]] = cur_t + np.clip(
                            clipped - cur_t, -max_d, max_d)

        # Hold position on unclaimed actuators (gravity compensation —
        # prevents limp arms from toppling the robot)
        for aid in unclaimed_ids:
            targets[aid] = hold_qpos_targets[aid]
            pd_mask[aid] = True

        # --- Step physics with velocity drive ---
        # Set base XY velocity and yaw rate each substep.  Also zero out
        # roll and pitch angular velocity — without this, the wheel-floor
        # contact friction opposes the forced linear velocity and creates
        # a pitching torque that tips the robot over.  Z velocity is left
        # to physics (gravity, settling).
        t_p0 = pc()
        for _ in range(steps_per_frame):
            # PD tick: torques from the LIVE state, held targets
            if step_count % pd_every == 0:
                pd = controller.step(targets, {
                    "joint_angles": data.qpos,
                    "joint_velocities": data.qvel})
                data.ctrl[:] = np.where(pd_mask, pd, 0.0)
            if base_dof is not None:
                data.qvel[base_dof + 0] = base_vx
                data.qvel[base_dof + 1] = base_vy
                # qvel[base_dof + 2] (Z) left to physics
                data.qvel[base_dof + 3] = 0.0  # no roll
                data.qvel[base_dof + 4] = 0.0  # no pitch
                data.qvel[base_dof + 5] = base_wz
            mujoco.mj_step(model, data)
            step_count += 1
            if step_count % cam_every == 0:
                t_c0 = pc()
                if bench["roundrobin"]:
                    rig.render(data, [cam_names[cam_tick % len(cam_names)]])
                    cam_tick += 1
                else:
                    rig.render(data)
                tm["cam"] += pc() - t_c0
        tm["phys"] += pc() - t_p0

        # Logging
        if logging_active:
            logger.record(obs)
        cur_l = held(glfw.KEY_L)
        if cur_l and not prev_l:
            logging_active = not logging_active
            print(f"Logging: {'ON' if logging_active else 'OFF'}")
        prev_l = cur_l

        cur_c = held(glfw.KEY_C)
        if cur_c and not prev_c:
            cam_dir.mkdir(parents=True, exist_ok=True)
            stamp = _time.strftime("%H%M%S")
            for cname, img in rig.images.items():
                cv2.imwrite(str(cam_dir / f"{cname}_{stamp}.png"),
                            cv2.cvtColor(img, cv2.COLOR_RGB2BGR))
            print(f"Camera images saved: {cam_dir}/*_{stamp}.png")
        prev_c = cur_c

        # Camera follow
        cam.lookat[:] = data.xpos[base_body_id]
        qw, qx, qy, qz = data.xquat[base_body_id]
        yaw_deg = math.degrees(
            math.atan2(2.0 * (qw * qz + qx * qy),
                       1.0 - 2.0 * (qy * qy + qz * qz)))
        cam.azimuth = yaw_deg + 90

        # Render
        width, height = glfw.get_framebuffer_size(window)
        viewport = mujoco.MjrRect(0, 0, width, height)
        t_r0 = pc()
        mujoco.mjv_updateScene(
            model, data, opt, None, cam,
            mujoco.mjtCatBit.mjCAT_ALL, scene_vis)
        mujoco.mjr_render(viewport, scene_vis, context)
        t_r1 = pc()
        tm["render"] += t_r1 - t_r0
        # Text is drawn into small RGB bitmaps with OpenCV and blitted with
        # one mjr_drawPixels each. mjr_overlay draws one glyph per GL call,
        # and on this VM's vmwgfx driver every such call leaks a resource id:
        # a ~200 glyph HUD aborted the process at frame ~250 ("Illegal
        # COTable id"). One single-space overlay is kept per frame because the
        # first mjr_drawPixels right after mjr_render is otherwise dropped
        # (eagle inset blank); a few glyphs/frame is far below the limit.
        def blit(img, left, bottom):
            # drawPixels wants a FLAT contiguous uint8 array, bottom-up rows
            h, w = img.shape[:2]
            flat = np.ascontiguousarray(np.flipud(img)).ravel()
            mujoco.mjr_drawPixels(
                flat, None, mujoco.MjrRect(left, bottom, w, h), context)

        def text_bitmap(rows, w, label_w, keys=()):
            line_h, key_h, font = 20, 24, cv2.FONT_HERSHEY_SIMPLEX
            # Key legend: keycap icon + short label, flowed left to right and
            # wrapped to the panel width, to use as little height as possible.
            layout, x, line = [], 6, 0
            for key, label in keys:
                kw = cv2.getTextSize(key, font, 0.4, 1)[0][0] + 8
                lw = cv2.getTextSize(label, font, 0.4, 1)[0][0]
                if x + kw + 4 + lw > w - 6 and x > 6:
                    x, line = 6, line + 1
                layout.append((key, label, x, line, kw))
                x += kw + 4 + lw + 12
            top = line_h * len(rows) + 8
            h = top + (key_h * (line + 1) + 6 if keys else 0)
            bmp = np.full((h, w, 3), 45, np.uint8)
            for i, (lab, val) in enumerate(rows):
                y = line_h * (i + 1) - 3
                cv2.putText(bmp, lab, (6, y), cv2.FONT_HERSHEY_SIMPLEX,
                            0.45, (190, 190, 190), 1, cv2.LINE_AA)
                cv2.putText(bmp, val, (label_w, y), cv2.FONT_HERSHEY_SIMPLEX,
                            0.45, (255, 255, 255), 1, cv2.LINE_AA)
            if keys:
                cv2.line(bmp, (6, top - 2), (w - 6, top - 2), (110, 110, 110), 1)
            for key, label, kx, ln, kw in layout:
                y = top + key_h * ln + 17
                cv2.rectangle(bmp, (kx, y - 14), (kx + kw, y + 4),
                              (80, 80, 80), -1)
                cv2.rectangle(bmp, (kx, y - 14), (kx + kw, y + 4),
                              (200, 200, 200), 1)
                cv2.putText(bmp, key, (kx + 4, y), font, 0.4,
                            (255, 255, 255), 1, cv2.LINE_AA)
                cv2.putText(bmp, label, (kx + kw + 4, y), font, 0.4,
                            (150, 220, 150), 1, cv2.LINE_AA)
            return bmp

        if SHOW_HUD or SHOW_CAMERA_INSETS:
            mujoco.mjr_overlay(
                mujoco.mjtFont.mjFONT_NORMAL,
                mujoco.mjtGridPos.mjGRID_TOPLEFT, viewport, " ", None, context)
        if SHOW_HUD:
            now = _time.time()
            dt_wall = now - hud_state["last"]
            hud_state["last"] = now
            # Smooth frame TIME, not fps: averaging 1/dt is dominated by the
            # fast frames between camera ticks and overstates the rate.
            hud_state["ms"] += 0.1 * (1000.0 * dt_wall - hud_state["ms"])
            ds = drive_state.get("base", {})
            speed = math.hypot(base_vx, base_vy)
            hud = text_bitmap([
                ("sim time", f"{t:.2f} s"),
                ("base speed (m/s)", f"{speed:.2f}"),
                ("base vx, vy (m/s)", f"{base_vx:+.2f}, {base_vy:+.2f}"),
                ("yaw rate (rad/s)", f"{base_wz:+.2f}"),
                ("yaw (deg)", f"{yaw_deg:+.1f}"),
                ("position x, y, z (m)", f"{data.qpos[0]:.2f}, "
                 f"{data.qpos[1]:.2f}, {data.qpos[2]:.3f}"),
                ("frame (ms, fps)", f"{hud_state['ms']:.0f}, "
                 f"{1000.0 / max(hud_state['ms'], 1e-6):.1f}"),
                ("cmd lin, ang", f"{ds.get('linear', 0):+.2f}, "
                 f"{ds.get('angular', 0):+.2f}"),
                ("selected (Tab,1-8)", (
                    f"{jog_sel['side'][0].upper()} "
                    + (f"grip = {hold_qpos_targets[jog_tables[jog_sel['side']][GRIP_IDX][0][0]]:.3f} m"
                       if jog_sel["idx"] == GRIP_IDX else
                       f"joint {jog_sel['idx'] + 1} = "
                       f"{hold_qpos_targets[jog_tables[jog_sel['side']][jog_sel['idx']][0][0]]:+.2f} rad"))),
            ] + ([("arms (T toggles)", (
                "MANUAL" if not teleop["on"] else
                "TELEOP tracking" if teleop["engaged"] else
                "TELEOP no body, holding"))] if teleop is not None else []),
                400, 180, hud_keys)
            blit(hud, 8, height - hud.shape[0] - 8)
        if SHOW_CAMERA_INSETS:
            # One row of insets along the bottom: the simulated cameras, plus
            # the operator webcam in teleop runs. Each is scaled to fit the
            # window width (at most half size), with its name burned into the
            # top-left corner. Images are top-down; blit flips them.
            tiles = list(rig.images.items())
            if teleop is not None and preview:
                pf = teleop.get("preview_frame")
                tiles.append(("operator_cam", None if pf is None else
                              cv2.cvtColor(pf, cv2.COLOR_BGR2RGB)))
            gap = 8
            iw = min(320, (width - gap * (len(tiles) + 1)) // len(tiles))
            ih = iw * 3 // 4
            x = gap
            for cname, img in tiles:
                # The simulated cameras only change on their render ticks, so
                # keep the scaled, labelled tile until the source array does.
                cached = inset_cache.get(cname)
                if img is not None and cached is not None \
                        and cached[0] is img and cached[1].shape[1] == iw:
                    small = cached[1]
                else:
                    if img is None:  # operator camera: no frame delivered yet
                        small = np.full((ih, iw, 3), 40, np.uint8)
                    else:
                        small = cv2.resize(img, (iw, ih),
                                           interpolation=cv2.INTER_AREA)
                    cv2.rectangle(small, (0, 0), (len(cname) * 9 + 10, 20),
                                  (45, 45, 45), -1)
                    cv2.putText(small, cname, (5, 15),
                                cv2.FONT_HERSHEY_SIMPLEX, 0.5,
                                (255, 255, 255), 1, cv2.LINE_AA)
                    inset_cache[cname] = (img, small)
                blit(small, x, gap)
                x += iw + gap
        tm["hud_insets"] += pc() - t_r1
        p_now = glfw.get_key(window, glfw.KEY_P) == glfw.PRESS
        due = snapshot_every > 0 and \
            _time.time() - snap_state["last"] >= snapshot_every
        if (p_now and not snap_state["p_down"]) or due:
            snap_state["last"] = _time.time()
            rgb = np.zeros((height, width, 3), dtype=np.uint8)
            mujoco.mjr_readPixels(rgb, None, viewport, context)
            save_snapshot(rgb)
        snap_state["p_down"] = p_now
        if bench["snap_dir"] and frame == bench["snap_frame"]:
            sd = Path(bench["snap_dir"]); sd.mkdir(parents=True, exist_ok=True)
            rgb = np.zeros((height, width, 3), dtype=np.uint8)
            mujoco.mjr_readPixels(rgb, None, viewport, context)
            cv2.imwrite(str(sd / "main.png"),
                        cv2.cvtColor(np.flipud(rgb), cv2.COLOR_RGB2BGR))
            for cname, img in rig.images.items():
                cv2.imwrite(str(sd / f"{cname}.png"),
                            cv2.cvtColor(img, cv2.COLOR_RGB2BGR))
        t_s0 = pc()
        glfw.swap_buffers(window)
        glfw.poll_events()
        if bench["finish"]:
            mujoco.mjr_finish()
        tm["swap_poll"] += pc() - t_s0
        if bench["frames"]:
            rows.append((tm['cam'] > tick_prev, 1000 * (pc() - t_p0),
                         1000 * (tm['render'] - r_prev), 1000 * (pc() - t_s0)))
            tick_prev = tm['cam']; r_prev = tm['render']

        if bench["vsync"] == 0:
            # No vsync pacing: hold the viewer to VIEWER_HZ so sim time
            # never runs faster than wall time.
            slack = 1.0 / VIEWER_HZ - (pc() - t_f0)
            if slack > 0:
                _time.sleep(slack)

        frame += 1
        if bench["frames"]:
            if frame == 10:  # discard warm-up
                tm = dict.fromkeys(tm, 0.0)
                t_bench0 = pc()
            elif frame >= 10 + bench["frames"]:
                n = bench["frames"]
                wall = pc() - t_bench0
                print(f"BENCH {n} frames: {1000 * wall / n:.0f} ms/frame "
                      f"({n / wall:.1f} fps) | " + " ".join(
                          f"{k}={1000 * v / n:.0f}ms" for k, v in tm.items()))
                for lab, sel in (("tick", True), ("no-tick", False)):
                    rr = [r for r in rows[10:] if r[0] == sel]
                    if rr:
                        m = lambda i: sum(r[i] for r in rr) / len(rr)
                        print(f"BENCH {lab}: {len(rr)} frames, "
                              f"total={m(1):.0f}ms render={m(2):.0f}ms "
                              f"swap_poll={m(3):.0f}ms")
                break

        # --- DEBUG ---
        verbose = (frame <= 10) or (frame % 60 == 0)
        if verbose:
            ds = drive_state.get("base", {})
            print(f"  f={frame:5d}  t={t:.2f}  "
                  f"lin={ds.get('linear',0):+.2f} ang={ds.get('angular',0):+.2f}  "
                  f"vel=[{base_vx:+.2f},{base_vy:+.2f}]  wz={base_wz:+.2f}  "
                  f"yaw={yaw_deg:+.1f}°  "
                  f"sel={jog_sel['side'][0].upper()}{jog_sel['idx'] + 1} "
                  f"tgt={hold_qpos_targets[jog_tables[jog_sel['side']][jog_sel['idx']][0][0]]:+.3f}  "
                  f"pos={data.qpos[0:3].round(3)}")

        if held(glfw.KEY_ESCAPE):
            print("ESC pressed")
            break

      except Exception as e:
            print(f"EXCEPTION in loop at frame {frame}: {e}")
            import traceback; traceback.print_exc()
            break

    # ---------------------------------------------------------------
    print(f"\nLoop exited after {frame} frames.")
    if logging_active and len(logger.trajectory) > 0:
        logger.save()
    if teleop is not None:
        source.cleanup()
    glfw.terminate()
    print("Done.")


# ===================================================================
# CLI
# ===================================================================

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--scene", default=DEFAULT_SCENE)
    parser.add_argument("--spawn", type=float, nargs=3, default=DEFAULT_SPAWN,
                        metavar=("X", "Y", "Z"))
    parser.add_argument("--no-spawn", action="store_true")
    parser.add_argument("--mode", choices=["manual", "auto", "teleop"],
                        default="manual",
                        help="manual: keyboard (default); auto: future policy "
                             "(not implemented); teleop: arms start on the "
                             "keyboard, T switches them to the webcam operator")
    parser.add_argument("--camera", type=int, default=0,
                        help="webcam device index for teleop (0=built-in, "
                             "1+=USB)")
    parser.add_argument("--snapshot-every", type=float, default=0.0,
                        help="save sim + camera PNGs every N seconds "
                             "(also: press P in the sim window)")
    parser.add_argument("--snapshot-dir", default=None,
                        help="where snapshots go (default: ./snapshots)")
    parser.add_argument("--no-preview", action="store_true",
                        help="teleop: don't show the live camera window")
    args = parser.parse_args()
    if args.mode == "auto":
        parser.error("--mode auto is a placeholder for a future policy and "
                     "is not implemented yet")

    run(
        scene=args.scene,
        spawn_pos=None if args.no_spawn else args.spawn,
        groups=CONTROL_GROUPS,
        policy=DEFAULT_POLICY,
        mode=args.mode,
        camera=args.camera,
        preview=not args.no_preview,
        snapshot_every=args.snapshot_every,
        snapshot_dir=args.snapshot_dir,
    )


if __name__ == "__main__":
    main()